namespace LabSystemTests
{
    [TestFixture]
    public class LabSystemTestFixture
    {
        [SetUp]
        public void SetUp()
        {
            // Initialize test environment
        }

        [TearDown]
        public void TearDown()
        {
            // Clean up after tests
        }

        [Test]
        public void TestLabInchargePerformsLabTestsAndUpdatesReports()
        {
            // Arrange
            var labIncharge = new LabIncharge();
            var report = new Report();

            // Act
            labIncharge.PerformLabTests();
            labIncharge.UpdateReport(report);

            // Assert
            Assert.AreEqual(report.Status, ReportStatus.Updated);
        }

        [Test]
        public void TestLabInchargeSetsFlagInPrescription()
        {
            // Arrange
            var labIncharge = new LabIncharge();
            var prescription = new Prescription();

            // Act
            labIncharge.SetFlagInPrescription(prescription);

            // Assert
            Assert.IsTrue(prescription.FlagSet);
        }

        [Test]
        public void TestChemistDeliversMedicineAndSetsFlagInPrescription()
        {
            // Arrange
            var chemist = new Chemist();
            var prescription = new Prescription();

            // Act
            chemist.DeliverMedicine(prescription);
            chemist.SetFlagInPrescription(prescription);

            // Assert
            Assert.IsTrue(prescription.FlagSet);
        }

        [Test]
        public void TestAdminViewsInvoiceAndReports()
        {
            // Arrange
            var admin = new Admin();
            var invoice = new Invoice();
            var report = new Report();

            // Act
            admin.ViewInvoice(invoice);
            admin.ViewReports(report);

            // Assert
            Assert.AreEqual(invoice.Status, InvoiceStatus.Viewed);
            Assert.AreEqual(report.Status, ReportStatus.Viewed);
        }
    }
}
